/**
 * EXTERIOR-COMPLETE E13 research: one whole case of the review loop (contract v3.42), end to end, on a real house.
 *
 *   npx vite-node research/ai-assist/section-levels-case.ts -- --run <CV_ONLY run dir> --cache <byte cache> --out <dir> [--models claude-haiku-5-5,claude-opus-5-5] [--fixture answer.json]
 *
 * 1. PROBLEM, generated by the analyzer from its own record: a section frame whose metric registration is MISSING
 *    while the numeric reader saw number-like ink on it (its glyphs under the legibility gate). The question names no
 *    value, no hypothesis and none of the checks that will be run.
 * 2. ASK the cheaper model first (round 0), the stronger one only if the first answer does not pass (round 1); every
 *    call reserved and settled in the spend ledger. The image is the frame's exact bytes.
 * 3. VALIDATE without a reference answer (`checkLevelReadings`): each reading must parse as a level, sit over a level
 *    symbol found in the same bytes, and lie on the ladder the other readings make; the published building height is
 *    the second, independent check.
 * 4. PROPOSE `ADD_SOURCE_READINGS` on that frame, at the CV_ONLY model's revision.
 * 5. VARIANT: the metric evidence with the admitted readings as LEVEL_DATUM (`VISION_VALIDATED`) and the section's
 *    registration; the solver on it, and — for an identical-input comparison — on the evidence as it was.
 * 6. COMPARE (the regression detector, compile errors, the ridge against the print and the published height) and
 *    DECIDE: accepted only with no regression and a source check passed; otherwise rolled back, the CV model standing.
 *
 * With `--fixture` the answer is read from a file instead of a provider: the wrong-but-confident test runs through the
 * same validation, proposal and decision. Research only; nothing under `packages/` imports this file.
 */
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { AI_LOOP_CONTRACT_VERSION, aiAnswerJsonSchema, runReviewLoop } from '@buildapp/source-vision'
import type { AiAnswer, AnalyzerProblem, CheckResult, LoopCall } from '@buildapp/source-vision'
import { checkLevelReadings, levelEvidenceFromReadings, supersededLevels } from '@buildapp/source-metrics'
import type { ExternalLevelReading, LevelLadderVerdict, MetricEvidenceSet } from '@buildapp/source-metrics'
import { SourcePackageSchema, decodeImage, fileByteCache } from '@buildapp/source-package'
import type { SourceObservationGraph } from '@buildapp/source-observations'
import { claudeCodeStructured } from './claude-code-reasoner.js'
import type { CliCall } from './claude-code-reasoner.js'
import { ledgerGuard } from './spend-ledger.js'

const here = dirname(fileURLToPath(import.meta.url))
const repo = join(here, '..', '..')
const argv = process.argv.slice(2).filter((a) => a !== '--')
const arg = (k: string): string | undefined => {
  const i = argv.indexOf(`--${k}`)
  return i >= 0 ? argv[i + 1] : undefined
}
const runDir = arg('run') as string
const cacheDir = arg('cache') as string
const out = arg('out') as string
const models = (arg('models') ?? 'claude-haiku-5-5,claude-opus-5-5').split(',')
const fixture = arg('fixture')
const replay = arg('replay')
mkdirSync(out, { recursive: true })
const write = (name: string, v: unknown) => writeFileSync(join(out, name), `${JSON.stringify(v, null, 2)}\n`)
const sha = (b: Uint8Array | string) => createHash('sha256').update(b).digest('hex')

const pkg = SourcePackageSchema.parse(JSON.parse(readFileSync(join(runDir, 'source-package.json'), 'utf8')))
const graph = JSON.parse(readFileSync(join(runDir, 'observation-graph.json'), 'utf8')) as SourceObservationGraph
const metrics = JSON.parse(readFileSync(join(runDir, 'metric-evidence.json'), 'utf8')) as MetricEvidenceSet
const cache = fileByteCache(cacheDir)
const solve = (metricsPath: string, dir: string) => {
  execFileSync('npx', ['vite-node', 'packages/analysis-service/scripts/second-house.ts', '--', '--package', join(runDir, 'source-package.json'), '--graph', join(runDir, 'observation-graph.json'), '--metrics', metricsPath, '--cache', cacheDir, '--out', dir, '--views'], { cwd: repo, stdio: ['ignore', 'ignore', 'inherit'], timeout: 900_000 })
}
// the CV_ONLY model of this code on these inputs: the base revision every proposal is checked against
const cvDir = join(out, 'cv')
solve(join(runDir, 'metric-evidence.json'), cvDir)
const cvSummary = JSON.parse(readFileSync(join(cvDir, 'result-summary.json'), 'utf8')) as { modelHash: string }

// --- 1. the problem, from the analyzer's own record -----------------------------------------------------------------
const sections = graph.coordinateFrames.filter((f) => f.roles.projection === 'ORTHOGRAPHIC_SECTION')
// a registration needs two level marks; one read (or none) with number-like ink left over is the problem
const frame = sections.find((f) => metrics.unresolved.some((u) => u.frameId === f.id && u.status === 'MISSING' && u.what.startsWith('a metric registration')) && metrics.evidence.filter((e) => e.kind === 'LEVEL_DATUM' && e.frameId === f.id).length < 2 && (metrics.ocrTokens ?? []).filter((t) => t.frameId === f.id).length >= 3)
if (!frame) {
  console.log('no section of this run lacks a registration while showing number-like ink: no problem to ask')
  process.exit(0)
}
const asset = pkg.assets.find((a) => a.id === frame.assetId)
const variant = asset?.variants.find((v) => v.byteHash === frame.variantByteHash)
if (!asset || !variant) throw new Error(`no variant for ${frame.id}`)
const got = await cache.get(variant.url)
if (!got) throw new Error(`bytes of ${variant.url} not in the cache`)
const bytes = got.bytes
if (sha(bytes) !== frame.variantByteHash) throw new Error('the cached bytes are not the frame\'s')
const raster = decodeImage(bytes)
const tokens = (metrics.ocrTokens ?? []).filter((t) => t.frameId === frame.id).length
const problem: AnalyzerProblem = {
  contractVersion: AI_LOOP_CONTRACT_VERSION,
  problemId: `problem-section-levels-${frame.id}`,
  runId: runDir.split('/').filter(Boolean).pop() as string,
  modelRevision: cvSummary.modelHash,
  modelHash: cvSummary.modelHash,
  code: 'UNCHECKED',
  task: 'READ_TEXT',
  subject: { kind: 'SECTION_LEVEL_MARKS', frameId: frame.id },
  question: 'This is a building section (a vertical cut through a house). List every level mark printed on it: a signed number in metres such as +2,93, ±0,00 or -0,47, printed above a small triangle symbol that points at a line. For each, give the text exactly as printed and a tight box around the printed text only. If one is there but not legible, include it with legible=false. Numbers that are not level marks (plain dimensions such as 297, angles) are kind OTHER or may be left out. If you cannot see level marks at all, answer UNKNOWN.',
  facts: [{ what: 'number-like tokens the numeric reader found on this sheet, of which it read fewer than two level marks (a registration needs two)', value: tokens, provenance: 'metric-evidence.ocrTokens' }],
  sources: [{ assetId: asset.id, byteHash: frame.variantByteHash, frameId: frame.id, widthPx: frame.size.width, heightPx: frame.size.height, document: frame.roles.document, projection: frame.roles.projection, side: frame.roles.view ?? 'UNKNOWN', storey: frame.roles.storey ?? 'UNKNOWN', cropRectPx: { x0: 0, y0: 0, x1: frame.size.width, y1: frame.size.height }, transform: { scale: 1, offsetPx: { x: 0, y: 0 } } }],
  allowedOps: ['ADD_SOURCE_READINGS'],
  limits: { maxObservations: 24, maxRounds: Math.min(2, models.length), maxUsd: 0.5 },
}
write('problem.json', problem)
const published = pkg.publishedFacts?.find((f) => f.key === 'building_height')

// --- 2. ask ---------------------------------------------------------------------------------------------------------
const guard = ledgerGuard(join(here, 'spend-ledger.json'), 'E13 section-levels case')
const traces: CliCall[] = []
const answers: Array<{ round: number; model: string; raw: unknown }> = []
const SYSTEM = 'You read printed labels on one architectural drawing. Look only at the image. Report what is printed, where it is, and how sure you are; never guess a value to complete a pattern. Coordinates are fractions of the image, origin top left, y down.'
const ask = async (p: AnalyzerProblem, round: number): Promise<{ raw: unknown; call: LoopCall } | { unavailable: string; call?: LoopCall }> => {
  if (fixture) {
    const raw = JSON.parse(readFileSync(fixture, 'utf8'))
    answers.push({ round, model: 'fixture', raw })
    return { raw, call: { model: 'fixture', sessionId: null, estimatedCostUsd: 0, status: 'FIXTURE' } }
  }
  if (replay) {
    // a recorded live answer, replayed through the current checks: the model's words are the same, no new call is made
    const rec = (JSON.parse(readFileSync(replay, 'utf8')) as Array<{ round: number; model: string; raw: unknown; sessionId?: string }>).find((x) => x.round === round)
    if (!rec) return { unavailable: 'no recorded answer for this round' }
    answers.push({ round, model: rec.model, raw: rec.raw })
    return { raw: rec.raw, call: { model: rec.model, sessionId: rec.sessionId ?? null, estimatedCostUsd: 0, status: 'REPLAYED' } }
  }
  const model = models[round]
  if (!model) return { unavailable: 'no further model' }
  let call: CliCall | undefined
  try {
    const raw = await claudeCodeStructured({ model, system: SYSTEM, imagePng: bytes, mediaType: variant.mediaType ?? 'image/jpeg', text: `${p.question}\n\nThe image is ${p.sources[0].widthPx} × ${p.sources[0].heightPx} px. Source index 0.`, schema: aiAnswerJsonSchema(p.limits.maxObservations), budgetUsd: model.includes('haiku') ? 0.05 : 0.4, onCall: (c) => (call = c), guard, what: p.problemId })
    answers.push({ round, model, raw, sessionId: call?.sessionId ?? null } as { round: number; model: string; raw: unknown })
    return { raw, call: { model, sessionId: call?.sessionId ?? null, estimatedCostUsd: call?.estimatedCostUsd ?? null, status: call?.status ?? 'OK' } }
  } catch (e) {
    return { unavailable: (e as Error).message.slice(0, 200), ...(call ? { call: { model, sessionId: call.sessionId, estimatedCostUsd: call.estimatedCostUsd, status: call.status } } : {}) }
  } finally {
    if (call) traces.push(call)
  }
}

// --- 3. validate ----------------------------------------------------------------------------------------------------
let verdict: LevelLadderVerdict | undefined
let readings: ExternalLevelReading[] = []
let readingObs: number[] = []
const validate = (answer: AiAnswer) => {
  readingObs = answer.observations.map((o, i) => ({ o, i })).filter(({ o }) => o.kind === 'LEVEL_MARK' && o.legible && o.textAsPrinted).map(({ i }) => i)
  readings = readingObs.map((i) => {
    const o = answer.observations[i]
    const r = o.regionNorm
    return { text: o.textAsPrinted as string, boxPx: { x0: Math.round(r.x0 * raster.width), y0: Math.round(r.y0 * raster.height), x1: Math.round(r.x1 * raster.width), y1: Math.round(r.y1 * raster.height) }, classConfidence: o.classConfidence }
  })
  // where each label stands: the reader's box, or the numeric reader's own token inside it — the drawing decides, by
  // which places put more marks on one ladder; every admitted mark still has to stand on it and meet the published height
  const pub = published ? { key: 'building_height', valueM: published.value } : undefined
  const byBox = checkLevelReadings(raster, readings, pub)
  const byToken = checkLevelReadings(raster, readings, pub, (metrics.ocrTokens ?? []).filter((t) => t.frameId === frame.id).map((t) => t.box))
  const score = (x: LevelLadderVerdict) => (x.admitted ? 1000 : 0) + (x.published?.agrees ? 100 : 0) + x.checks.filter((c) => c.status === 'ON_LADDER').length
  verdict = score(byToken) > score(byBox) ? byToken : byBox
  const checks: CheckResult[] = verdict.checks.map((c) => ({ name: `reading ${c.index} "${c.text}"`, passed: c.status === 'ON_LADDER', detail: c.why }))
  checks.push({ name: 'ladder', passed: verdict.admitted, detail: verdict.why })
  if (verdict.published) checks.push({ name: 'published building height', passed: verdict.published.agrees, detail: `${verdict.published.spanM} m against ${verdict.published.valueM} m` })
  // a ladder alone checks the readings against each other; a second, independent check must agree before anything is used
  const enough = verdict.admitted && verdict.published?.agrees === true
  return { usable: verdict.checks.filter((c) => c.status === 'ON_LADDER').map((c) => readingObs[c.index]), checks, enough, why: verdict.admitted ? (verdict.published ? (verdict.published.agrees ? verdict.why : `the ladder stands but the published height disagrees (${verdict.published.spanM} vs ${verdict.published.valueM} m)`) : 'the ladder stands, but no published height corroborates it') : verdict.why }
}

// --- 4–6. propose, build, compare -----------------------------------------------------------------------------------
type Variant = { aiDir: string; cvDir: string }
const buildVariant = async (): Promise<Variant> => {
  const v = verdict as LevelLadderVerdict
  const reader = { id: 'vision.claude-code-cli', model: answers[answers.length - 1]?.model ?? 'unknown' }
  const added = levelEvidenceFromReadings(frame, readings, v, reader)
  // the numeric reader's own marks on the section the admitted ladder overrules: one label read twice, or a misread
  const superseded = supersededLevels(metrics.evidence, frame.id, readings, v)
  writeFileSync(join(out, 'superseded.json'), `${JSON.stringify(superseded, null, 2)}\n`)
  const gone = new Set(superseded.map((x) => x.evidenceId))
  const augmented: MetricEvidenceSet = {
    ...metrics,
    evidence: [...metrics.evidence.filter((e) => !gone.has(e.id)), ...added.evidence],
    coordinateRegistrations: [...metrics.coordinateRegistrations, ...(added.registration ? [added.registration] : [])],
    unresolved: metrics.unresolved.filter((u) => !(u.frameId === frame.id && u.what.startsWith('a metric registration'))),
  }
  writeFileSync(join(out, 'metric-evidence-ai.json'), JSON.stringify(augmented))
  const aiDir = join(out, 'ai')
  solve(join(out, 'metric-evidence-ai.json'), aiDir)
  return { aiDir, cvDir }
}
type Plane = { datum: { x: number; y: number; z: number }; downslope: { x: number; z: number }; pitchDeg: number; boundary: Array<{ x: number; z: number }>; id: string }
type GableRoof = { id: string; kind: string; ridgeAxis: 'X' | 'Z'; pitchDeg: number; eaveOffset: number; levelId: string; footprint: { minX: number; maxX: number; minZ: number; maxZ: number } }
/** The main roof's ridge: the highest point of its planes, or of a gable stated as a roof (eaves at the walls' line). */
const ridgeOf = (dir: string): number => {
  const m = JSON.parse(readFileSync(join(dir, 'model.json'), 'utf8')) as { roofPlanes: Plane[]; roofs: GableRoof[]; levels: Array<{ id: string; elevation: number }> }
  const tops = m.roofPlanes.filter((p) => p.id.startsWith('roof-main')).flatMap((p) => p.boundary.map((q) => p.datum.y - ((q.x - p.datum.x) * p.downslope.x + (q.z - p.datum.z) * p.downslope.z) * Math.tan((p.pitchDeg * Math.PI) / 180)))
  for (const r of m.roofs.filter((x) => x.id === 'roof-main' && x.kind !== 'FLAT')) {
    const level = m.levels.find((l) => l.id === r.levelId)?.elevation ?? 0
    const half = (r.ridgeAxis === 'Z' ? r.footprint.maxX - r.footprint.minX : r.footprint.maxZ - r.footprint.minZ) / 2
    tops.push(level + r.eaveOffset + half * Math.tan((r.pitchDeg * Math.PI) / 180))
  }
  return Math.round(Math.max(...tops) * 1000) / 1000
}
const errorsOf = (dir: string): Record<string, number> => {
  const p = join(dir, 'compile-diagnostics.json')
  if (!existsSync(p)) return {}
  const d = JSON.parse(readFileSync(p, 'utf8')) as Array<{ severity: string; code: string }> | { diagnostics: Array<{ severity: string; code: string }> }
  return (Array.isArray(d) ? d : d.diagnostics).filter((x) => x.severity === 'ERROR').reduce<Record<string, number>>((a, x) => ({ ...a, [x.code]: (a[x.code] ?? 0) + 1 }), {})
}
const compare = (v: Variant) => {
  const lines = execFileSync('python3', ['-I', join(repo, 'research/exterior-complete/regress.py'), v.cvDir, v.aiDir], { encoding: 'utf8' }).split('\n').map((l) => l.trim()).filter((l) => l.length > 0 && !l.endsWith(':') && !l.startsWith('CHANGES') && !l.endsWith('SAME'))
  writeFileSync(join(out, 'cv-vs-ai.txt'), `${lines.join('\n')}\n`)
  const printedRidge = Math.max(...((verdict as LevelLadderVerdict).checks.filter((c) => c.status === 'ON_LADDER').map((c) => c.value as number)))
  // the terrain the published height is measured from: the ground mark the level check itself met it with (a section
  // may print the ground on both sides); without a published height there is nothing to measure from
  const printedTerrain = (verdict as LevelLadderVerdict).published?.groundM ?? Math.min(...((verdict as LevelLadderVerdict).checks.filter((c) => c.status === 'ON_LADDER').map((c) => c.value as number)))
  const cvRidge = ridgeOf(v.cvDir)
  const aiRidge = ridgeOf(v.aiDir)
  const sourceChecks: CheckResult[] = [
    { name: 'ridge against the printed ridge level', passed: Math.abs(aiRidge - printedRidge) <= 0.05 && Math.abs(aiRidge - printedRidge) < Math.abs(cvRidge - printedRidge), detail: `CV_ONLY ${cvRidge} m, with the readings ${aiRidge} m, printed ${printedRidge} m` },
    ...(published ? [{ name: 'ridge over the printed terrain against the published height', passed: Math.abs(aiRidge - printedTerrain - published.value) <= 0.05, detail: `${aiRidge} − (${printedTerrain}) = ${(aiRidge - printedTerrain).toFixed(3)} m, published ${published.value} m (CV_ONLY ${(cvRidge - printedTerrain).toFixed(3)} m)` }] : []),
  ]
  const regressions = lines.filter((l) => /^(LOST|MODEL LOST|RUN MISSING)/.test(l) || /\(needs a source\)/.test(l))
  // an entrance is lost when a door leaves the floor; a printed size is lost when a variant changes it
  type Op = { id: string; kind: string; sill: number; height: number; width: number; evidence?: { properties?: Record<string, string> } }
  const ops = (dir: string) => (JSON.parse(readFileSync(join(dir, 'model.json'), 'utf8')) as { openings: Op[] }).openings
  const after = new Map(ops(v.aiDir).map((o) => [o.id, o]))
  const unverified: string[] = []
  for (const o of ops(v.cvDir)) {
    const n = after.get(o.id)
    if (!n) continue
    if (o.kind === 'DOOR' && o.sill <= 0.05 && n.sill > 0.05) regressions.push(`${o.id}: a door at the floor moved off it (sill ${o.sill.toFixed(2)} -> ${n.sill.toFixed(2)})`)
    if (o.evidence?.properties?.height === 'SOURCE_EXACT' && Math.abs(n.height - o.height) > 0.03) regressions.push(`${o.id}: its printed height ${o.height.toFixed(2)} changed to ${n.height.toFixed(2)}`)
    // E13: the readings are levels; what they change in an opening through a new reading — an elevation the levels
    // registered now placing or sizing it — is a side effect nothing here checked: named, and the person decides. A
    // convention re-applied on the printed levels (an assumed head at the storey's printed ceiling) is the readings' own
    // effect, not a new reading.
    const read = (k: string): boolean => (n.evidence?.properties?.[k] ?? 'ASSUMED') !== 'ASSUMED'
    const moved = [
      ...(n.kind !== o.kind && read('kind') ? [`kind ${o.kind} -> ${n.kind} (${n.evidence?.properties?.kind})`] : []),
      ...(Math.abs(n.width - o.width) > 0.05 && read('width') ? [`width ${o.width.toFixed(2)} -> ${n.width.toFixed(2)} (${n.evidence?.properties?.width})`] : []),
      ...(Math.abs(n.sill - o.sill) > 0.1 && read('sill') ? [`sill ${o.sill.toFixed(2)} -> ${n.sill.toFixed(2)} (${n.evidence?.properties?.sill})`] : []),
      ...(Math.abs(n.height - o.height) > 0.1 && read('height') ? [`height ${o.height.toFixed(2)} -> ${n.height.toFixed(2)} (${n.evidence?.properties?.height})`] : []),
    ]
    if (moved.length > 0 && !regressions.some((r) => r.startsWith(`${o.id}:`))) unverified.push(`${o.id}: ${moved.join(', ')}`)
  }
  const aiHash = (JSON.parse(readFileSync(join(v.aiDir, 'result-summary.json'), 'utf8')) as { modelHash: string }).modelHash
  return { revision: aiHash, changedElements: lines.filter((l) => l.startsWith('CHANGED') || l.startsWith('ADDED')).map((l) => l.replace(/^CHANGED |^ADDED /, '').split(':')[0]), errorsAfter: errorsOf(v.aiDir), sourceChecks, regressions, unverified }
}

const result = await runReviewLoop<Variant>(problem, { revision: cvSummary.modelHash, errors: errorsOf(cvDir) }, {
  ask,
  validate,
  propose: (_a, usable, p) => ({ contractVersion: AI_LOOP_CONTRACT_VERSION, proposalId: `proposal-${p.problemId}`, problemId: p.problemId, baseRevision: p.modelHash, op: 'ADD_SOURCE_READINGS', target: frame.id, premises: usable, expectedEffect: 'the section is registered by its printed level marks: the ridge datum and the storeys\' levels come from the print, not from the knee-wall approximation', checks: ['each mark over a level symbol in the same bytes', 'one ladder (leave one out)', 'the published building height', 'compile errors not up', 'no regression', 'the ridge against the print'] }),
  buildVariant,
  compare,
})
write('answers.json', answers)
write('verdict.json', verdict ?? null)
write('decision.json', result.decision)
write('calls.json', traces.map(({ raw: _r, ...t }) => t))
console.log(JSON.stringify({ outcome: result.decision.outcome, why: result.decision.why, rounds: result.decision.rounds, ladder: verdict?.why, sourceChecks: result.decision.sourceChecks, calls: traces.map((t) => ({ model: t.modelRequested, returned: t.modelsReturned, session: t.sessionId, auth: t.authCategory, cost: t.estimatedCostUsd, tokens: t.usage })) }, null, 2))
